steps.tool_output:
            continue
        key = token[2:]
        if i + 1 < len(extra) and not extra[i + 1].startswith("--"):
            raw = extra[i + 1]
            i += 2
        else:
            raw = "true"  # bare flag
            i += 1
        try:
            kwargs[key] = json.loads(raw)
        except json.JSONDecodeError:
            kwargs[key] = raw
    return kwargs


def main(argv: list) -> int:
    parser = argparse.ArgumentParser(add_help=True, description=__doc__)
    parser.add_argument("command", help="tool name, or 'list' / 'reset'")
    parser.add_argument("--json", dest="json_args", default=None, help="JSON object of arguments")
    args, extra = parser.parse_known_args(argv)

    if args.command == "list":
        _emit({"ok": True, "result": sorted(REGISTRY.keys())})
        return 0
    if args.command == "reset":
        path = db.reset()
        _emit({"ok": True, "result": {"reset": True, "db_path": str(path)}})
        return 0

    if args.command not in REGISTRY:
        _emit(
            {
                "ok": False,
                "error": {
                    "type": "UnknownTool",
                    "message": f"Unknown tool '{args.command}'. Run `list` to see tools.",
                },
            }
        )
        return 0

    kwargs: dict = {}
    if args.json_args:
        try:
            parsed = json.loads(args.json_args)
        except json.JSONDecodeError as exc:
            _emit({"ok": False, "error": {"type": "JSONDecodeError", "message": str(exc)}})
            return 0
        if not isinstance(parsed, dict):
            _emit(
                {
                    "ok": False,
                    "error": {"type": "ValueError", "message": "--json must be a JSON object"},
                }
            )
            return 0
        kwargs.update(parsed)
    kwargs.update(_parse_extra(extra))

    try:
        result = REGISTRY[args.command](**kwargs)
        _emit({"ok": True, "result": result})
    except Exception as exc:  # noqa: BLE001 - surface every failure as an envelope
        _emit({"ok": False, "error": {"type": type(exc).__name__, "message": str(exc)}})
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

from typing import Any

from tau2.utils import dump_file, get_pydantic_hash, load_file
from tau2.utils.pydantic_utils import BaseModelNoExtra


class DB(BaseModelNoExtra):
    """Domain database.

    This is a base class for all domain databases.
    """

    @classmethod
    def load(cls, path: str) -> "DB":
        """Load the database from a structured file like JSON, YAML, or TOML."""
        data = load_file(path)
        return cls.model_validate(data)

    def dump(self, path: str, exclude_defaults: bool = False, **kwargs: Any) -> None:
        """Dump the database to a file."""
        data = self.model_dump(exclude_defaults=exclude_defaults)
        dump_file(path, data, **kwargs)

    def get_json_schema(self) -> dict[str, Any]:
        """Get the JSON schema of the database."""
        return self.model_json_schema()

    def get_hash(self) -> str:
        """Get the hash of the database."""
        return get_pydantic_hash(self)

    def get_statistics(self) -> dict[str, Any]:
        """Get the statistics of the database."""
        return {}
